import React from 'react';
import { searchItems } from './searchClient';

export const SearchResults = ({ query, page }) => {
  const [results, setResults] = React.useState([]);

  React.useEffect(() => {
    searchItems(query, page).then((items) => {
      setResults(items);
    });
  }, [query, page, setResults]);

  return <ul>{results.map((r) => <li key={r.id}>{r.title}</li>)}</ul>;
};

import { useEffect as useAfterRender, useReducer as useMachine } from 'react';
import { getOrder } from '@/services/orders';

function reducer(state: State, action: Action): State {
  return action.type === 'loaded' ? { ...state, order: action.order } : state;
}

export default function OrderView({ route }: Props) {
  const [state, send] = useMachine(reducer, { order: null });

  useAfterRender(() => {
    getOrder(route.orderId)
      .then((order) => send({ type: 'loaded', order }))
      .catch(() => send({ type: 'failed' }));
  }, [route.orderId]);

  return <OrderDetails order={state.order} />;
}

import { useLayoutEffect, useState } from 'react';
import { reportsClient } from '../clients/reports';

export function useReportRows(range: Range) {
  const [rows, setRows] = useState<Row[]>([]);

  useLayoutEffect(function loadRows() {
    reportsClient.rows.list({ range }).then(function (page) {
      if (page.items.length > 0) {
        setRows(page.items);
      }
    });
  }, [range]);

  return rows;
}

import { useEffect, useState } from 'react';
import { revealKey } from '../ipc/keys';

export function WorkspaceKey({ workspace }: { workspace: Workspace | null }) {
  const [key, setKey] = useState<string | null>(null);

  useEffect(() => {
    if (workspace == null) {
      return;
    }
    void revealKey(workspace.id).then((value) => {
      if (value) setKey(value);
    });
  }, [workspace]);

  return <code>{key}</code>;
}

import { useEffect, useState } from 'react';
import { rawRequest } from '../transport';

export function ChannelStats({ channel, rangeSeconds }: { channel: string; rangeSeconds: number }) {
  const [stats, setStats] = useState<Stats | null>(null);
  const [enabled, setEnabled] = useState(false);
  const update = setStats;

  useEffect(() => {
    const now = Math.floor(Date.now() / 1000);
    rawRequest('channel_stats', { body: JSON.stringify({ channel, from: now - rangeSeconds }) })
      .then((response) => {
        setEnabled(true);
        return response.json();
      })
      .then((payload) => update(payload.result));
  }, [channel, rangeSeconds]);

  return enabled ? <StatsTable stats={stats} /> : null;
}

