export function ExportVideo({ format }: { format: string }) {
  const [renderer, setRenderer] = useState<Renderer | null>(null);

  useEffect(() => {
    if (!renderer) {
      loadRenderer(format).then((next) => setRenderer(next));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [format]);

  return <Preview renderer={renderer} />;
}

import { useEffect, useRef, useState } from 'react';
import { completeAuthorization } from './oauth';

export function OAuthCallback({ code }: { code: string }) {
  const started = useRef(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (started.current) {
      return;
    }
    started.current = true;
    completeAuthorization(code).then((result) => setError(result.error));
  }, [code]);

  return error ? <Alert>{error}</Alert> : null;
}

