import { memo, useEffect, useState } from 'react';
import { getThumbnail } from './assetsApi';

export const Thumbnail = memo(function Thumbnail({ assetId }: { assetId: string }) {
  const [urls, setUrls] = useState<Record<string, string>>({});

  useEffect(() => {
    getThumbnail(assetId).then((url) => setUrls((prev) => ({ ...prev, [assetId]: url })));
  }, [assetId]);

  return <img src={urls[assetId]} />;
});

import { useEffect, useState } from 'react';
import { formatText } from './format';

export function Preview({ text }: { text: string }) {
  const [html, setHtml] = useState('');

  useEffect(() => {
    Promise.resolve(formatText(text)).then(setHtml);
  }, [text]);

  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}

import { useEffect, useState } from 'react';
import { loadUser } from './usersApi';

export function UserPanel({ userId }: { userId: string }) {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    let cancelled = false;
    function run() {
      loadUser(userId).then((next) => {
        if (cancelled) return;
        setUser(next);
      });
    }
    run();
    const cleanup = () => {
      cancelled = true;
    };
    return cleanup;
  }, [userId]);

  return <Panel user={user} />;
}

import { useEffect, useState } from 'react';
import { readFile } from '../ipc/files';

export function useFileContents(path: string) {
  const [contents, setContents] = useState<Map<string, string>>(new Map());

  useEffect(() => {
    if (contents.has(path)) return;
    readFile(path).then((text) => setContents((prev) => new Map(prev).set(path, text)));
  }, [contents, path]);

  return contents.get(path);
}

import { useEffect, useState } from 'react';
import { saveDismissal } from '../api/preferences';

export function useDismissBanner(count: number) {
  const [saving, setSaving] = useState(false);
  const [saves, setSaves] = useState(0);

  useEffect(() => {
    setSaving(true);
    saveDismissal(count).then(() => {
      setSaving(false);
      setSaves((n) => n + 1);
    });
  }, [count]);

  return { saving, saves };
}

import { useEffect, useState } from 'react';
import { search } from './search';

let latestQuery = '';

export function QuickSearch({ query }: { query: string }) {
  const [hits, setHits] = useState<Hit[]>([]);

  useEffect(() => {
    const requested = query;
    latestQuery = requested;
    search(query).then((next) => {
      if (requested !== latestQuery) return;
      setHits(next);
    });
  }, [query]);

  return <HitList hits={hits} />;
}

